import type { LucideIcon } from "lucide-react";

export type NavItem = {
  to: string;
  label: string;
  icon: LucideIcon;
  /** Extra words the command palette matches, such as "preferences" for Settings. */
  keywords?: readonly string[];
};

/** The sidebar: a main list, and a second list under a divider (settings, help). */
export type NavConfig = {
  primary: readonly NavItem[];
  secondary?: readonly NavItem[];
};

export function navItems(nav: NavConfig): NavItem[] {
  return [...nav.primary, ...(nav.secondary ?? [])];
}

/** `/` is active only on itself; any other item is active on itself and below it. */
export function isNavActive(pathname: string, to: string): boolean {
  if (to === "/") return pathname === "/";
  return pathname === to || pathname.startsWith(`${to}/`);
}

/** A chip in the header: an icon, a coloured dot and a short word. */
export const headerChipClass =
  "flex h-9 shrink-0 items-center gap-2 rounded-md px-2.5 text-xs text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring";

import { Activity, Settings } from "lucide-react";
import { expect, it } from "vitest";
import { isNavActive, navItems, type NavConfig } from "./nav";

const nav: NavConfig = {
  primary: [
    { to: "/", label: "Overview", icon: Activity },
    { to: "/items", label: "Items", icon: Activity },
  ],
  secondary: [{ to: "/settings", label: "Settings", icon: Settings, keywords: ["preferences"] }],
};

it("lists the secondary items after the primary ones", () => {
  expect(navItems(nav).map((item) => item.to)).toEqual(["/", "/items", "/settings"]);
  expect(navItems({ primary: nav.primary }).map((item) => item.to)).toEqual(["/", "/items"]);
});

it("marks `/` active only on itself", () => {
  expect(isNavActive("/", "/")).toBe(true);
  expect(isNavActive("/items", "/")).toBe(false);
});

it("marks any other item active on itself and on its child pages", () => {
  expect(isNavActive("/items", "/items")).toBe(true);
  expect(isNavActive("/items/42", "/items")).toBe(true);
  // A sibling whose path merely starts with the same letters is not a child.
  expect(isNavActive("/items-archive", "/items")).toBe(false);
});
